dir$s633.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$s633HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$s633HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
	case 'ma_dk_ngay':
      dir$s633HiddenColumnByDay(p);
	   break;
	case 'unit_id':
	 dir$s633DisabledMasterField(p, g);
      break;
	  case 'id_dh':
	 dir$s633DisabledMasterPort(p);
      break;
    default:
      break;
  }
}
function getRequest(o) {
   var p = document._dir;
   if (p.options.action =="NEW"){
	  p.showFilter("s633CR3", null, {_ngay_ct: p.valForm('ngay_ct'),_ngay_ct1: p.valForm('ngay_hl'),_ngay_ct2: p.valForm('ngay_hld'),_ma_gd: p.valForm('ma_gd'),_ma_noi_di: p.valForm('ma_noi_di'), _ten_noi_di: p.valForm('ten_noi_di'), _ma_noi_den: p.valForm('ma_noi_den'), _ten_noi_den: p.valForm('ten_noi_den')});	  
	  p.setInactive([ 'ma_noi_di','ma_noi_den'], false); 
	}
	else $.showToast(p.msg('OnLyNew'));
}

